<?php
declare(strict_types=1);require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../_helper.php';uks_require_access($pdo);if(!uks_can_manage($pdo))deny_access();$id=max(0,(int)($_GET['id']??$_POST['id']??0));$st=$pdo->prepare('SELECT * FROM uks_obat WHERE id=? LIMIT 1');$st->execute([$id]);$obat=$st->fetch();if(!$obat)exit('Obat tidak ditemukan.');$error='';$expiry=uks_expiry_state($obat['tanggal_kadaluarsa']??null);if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();$jenis=(string)$_POST['jenis'];$jumlah=(int)$_POST['jumlah'];$ket=trim((string)$_POST['keterangan']);if(!in_array($jenis,['masuk','keluar','koreksi'],true)||$jumlah<=0)$error='Jenis dan jumlah harus valid.';else{try{$pdo->beginTransaction();$lock=$pdo->prepare('SELECT id,nama,stok_saat_ini,tanggal_kadaluarsa FROM uks_obat WHERE id=? AND aktif=1 LIMIT 1 FOR UPDATE');$lock->execute([$id]);$current=$lock->fetch();if(!$current)throw new RuntimeException('Obat tidak tersedia atau sudah nonaktif.');if($jenis==='keluar'&&!empty($current['tanggal_kadaluarsa'])&&$current['tanggal_kadaluarsa']<date('Y-m-d'))throw new RuntimeException('Obat sudah kedaluwarsa dan tidak boleh dikeluarkan.');$before=(int)$current['stok_saat_ini'];$after=$jenis==='masuk'?$before+$jumlah:($jenis==='keluar'?$before-$jumlah:$jumlah);if($after<0)throw new RuntimeException('Stok tidak boleh menjadi negatif.');$pdo->prepare('UPDATE uks_obat SET stok_saat_ini=? WHERE id=?')->execute([$after,$id]);$pdo->prepare("INSERT INTO uks_stok_transaksi(obat_id,jenis,jumlah,stok_sebelum,stok_sesudah,tanggal,user_id,keterangan) VALUES(?,?,?,?,?,?,?,?)")->execute([$id,$jenis,$jumlah,$before,$after,date('Y-m-d'),user_id(),$ket]);uks_audit($pdo,'STOCK',$id,'Perubahan stok obat UKS');$pdo->commit();uks_flash('Stok berhasil diperbarui.');redirect('uks/obat/stok.php?id='.$id);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Gagal memperbarui stok.';}}}$tx=$pdo->prepare("SELECT t.*,u.nama AS user_nama FROM uks_stok_transaksi t LEFT JOIN users u ON u.id=t.user_id WHERE t.obat_id=? ORDER BY t.id DESC LIMIT 100");$tx->execute([$id]);$rows=$tx->fetchAll();$flash=uks_flash();$page_title='Kartu Stok UKS';require_once __DIR__.'/../../layouts/header.php';require_once __DIR__.'/../../layouts/sidebar.php';?><main class="main uks-module-page"><header class="topbar"><div class="topbar-title">Kartu Stok UKS</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content"><div class="page-header"><div><h1><?=e($obat['nama'])?></h1><p>Stok saat ini: <strong><?=number_format((int)$obat['stok_saat_ini'])?> <?=e($obat['satuan'])?></strong> · Kedaluwarsa: <strong><?=e($obat['tanggal_kadaluarsa']??'-')?></strong> <?php if($expiry['key']!=='none'):?><span class="badge bg-<?=$expiry['class']?>"><?=e($expiry['label'])?></span><?php endif;?></p></div><div class="page-header-actions"><button type="button" class="btn btn-primary" onclick="window.print()"><i class="bi bi-printer"></i> Cetak Kartu Stok</button><a class="btn btn-secondary" href="<?=BASE_URL?>uks/obat/index.php">Kembali</a></div></div><?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="form-card"><h3>Transaksi Stok</h3><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="form-group"><label>Jenis</label><select class="form-control" name="jenis"><option value="masuk">Stok Masuk</option><option value="keluar">Stok Keluar</option><option value="koreksi">Koreksi ke Stok Akhir</option></select></div><div class="form-group"><label>Jumlah</label><input class="form-control" type="number" min="1" name="jumlah" required></div><div class="form-group form-group-full"><label>Keterangan</label><input class="form-control" name="keterangan" placeholder="Sumber, alasan koreksi, dll."></div></div><div class="form-actions"><button class="btn btn-primary"><i class="bi bi-arrow-repeat"></i> Simpan Transaksi</button></div></form></div><div class="form-card"><h3>Riwayat Kartu Stok</h3><div class="table-responsive"><table class="data-table"><thead><tr><th>Tanggal</th><th>Jenis</th><th>Jumlah</th><th>Sebelum</th><th>Sesudah</th><th>Petugas</th><th>Keterangan</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty-state">Belum ada transaksi.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['tanggal'])?></td><td><?=e(ucfirst($r['jenis']))?></td><td><?=number_format((int)$r['jumlah'])?></td><td><?=number_format((int)$r['stok_sebelum'])?></td><td><strong><?=number_format((int)$r['stok_sesudah'])?></strong></td><td><?=e($r['user_nama']??'-')?></td><td><?=e($r['keterangan']??'-')?></td></tr><?php endforeach;endif;?></tbody></table></div></div></section></main><style>@media print{ @page{size:A4 portrait;margin:12mm;} body{background:#fff!important;} .sidebar,.topbar,.page-header-actions,.btn,form{display:none!important;} .main{margin:0!important;padding:0!important;width:100%!important;max-width:none!important;} .content{padding:0!important;} .form-card{box-shadow:none!important;border:1px solid #cbd5e1!important;break-inside:avoid;} .table-responsive{overflow:visible!important;} .data-table{font-size:10px!important;} h1{font-size:20px!important;} }</style><?php require_once __DIR__.'/../../layouts/footer.php';
